module student_mentor_finder(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] query_idx,\n    input [2:0] num_students,\n    input [7:0][15:0] student_A,\n    input [7:0][15:0] student_B,\n    output reg [2:0] mentor_idx,\n    output reg done,\n    output reg valid\n);\n\n    localparam IDLE = 2'b00;\n    localparam SEARCH = 2'b01;\n    localparam COMPARE = 2'b10;\n    localparam DONE = 2'b11;\n\n    reg [1:0] state, next_state;\n    reg [2:0] curr_idx;\n    reg [2:0] best_idx;\n    reg best_found;\n    \n    wire [15:0] query_A = student_A[query_idx];\n    wire [15:0] query_B = student_B[query_idx];\n    wire [15:0] cand_A = student_A[curr_idx];\n    wire [15:0] cand_B = student_B[curr_idx];\n    \n    wire valid_cand = (cand_A >= query_A) && (cand_B >= query_B) && (curr_idx != query_idx);\n    wire [15:0] diff_B = cand_B - query_B;\n    wire [15:0] diff_A = cand_A - query_A;\n    \n    wire [15:0] best_diff_B = student_B[best_idx] - query_B;\n    wire [15:0] best_diff_A = student_A[best_idx] - query_A;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n    \n    always @(*) begin\n        case (state)\n            IDLE: next_state = start ? SEARCH : IDLE;\n            SEARCH: begin\n                if (curr_idx >= num_students) next_state = DONE;\n                else if (valid_cand) next_state = COMPARE;\n                else next_state = SEARCH;\n            end\n            COMPARE: next_state = SEARCH;\n            DONE: next_state = start ? DONE : IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            curr_idx <= 3'b0;\n            best_idx <= 3'b0;\n            best_found <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        curr_idx <= 3'b0;\n                        best_found <= 1'b0;\n                    end\n                end\n                SEARCH: begin\n                    if (next_state == SEARCH) begin\n                        curr_idx <= curr_idx + 1;\n                    end\n                end\n                COMPARE: begin\n                    if (!best_found) begin\n                        best_idx <= curr_idx;\n                        best_found <= 1'b1;\n                    end else begin\n                        if (diff_B < best_diff_B) begin\n                            best_idx <= curr_idx;\n                        end else if (diff_B == best_diff_B && diff_A < best_diff_A) begin\n                            best_idx <= curr_idx;\n                        end\n                    end\n                    curr_idx <= curr_idx + 1;\n                end\n            endcase\n        end\n    end\n    \n    always @(*) begin\n        if (state == DONE) begin\n            done = 1'b1;\n            valid = best_found;\n            mentor_idx = best_found ? best_idx : 3'b0;\n        end else begin\n            done = 1'b0;\n            valid = 1'b0;\n            mentor_idx = 3'b0;\n        end\n    end\n\nendmodule